// ***************
// Filename: uart_top.sv
// Author: FPGA Cores 4 U
// Description: uart with its AXI4-Lite register interface, the block designs
//   and testbenches instantiate: the register map uart_regs (u_regs,
//   src/include/uart_regs.sv, ID "UART", VERSION and DATE at 0x00-0x08, the
//   registers from 0x10) and the logic uart (u_core, src/uart.sv), joined by
//   their register ports (cfg_* to the logic, sts_* back). Generated by
//   ip/scripts/regmap_gen.py from uart_regs.json and the ports of uart:
//   regenerate after changing either. Clock - aclk. Reset - synchronous
//   active low aresetn.
// Date: 2026-10-12
module uart_top #(
  parameter int CLK_HZ = 100_000_000,
  parameter int BAUD = 115_200,
  parameter int FIFO_DEPTH = 512
) (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  input  logic [7:0]  s_axis_tdata,
  input  logic        s_axis_tvalid,
  output logic        s_axis_tready,
  input  logic        s_axis_tlast,
  output logic [7:0]  m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast,
  output logic        uart_txd_o,
  input  logic        uart_rxd_i
);
  localparam logic [63:0] FCW64 = ((64'(BAUD) * 64'd16 << 32) + (64'(CLK_HZ) >> 1)) / 64'(CLK_HZ);
  // register ports between the register map and the logic
  logic [31:0] cfg_ctrl;
  logic [31:0] cfg_fcw;
  logic [31:0] cfg_status;
  logic cfg_status_wr;
  logic [31:0] sts_status;
  logic [31:0] sts_err_cnt;

  uart_regs #(
    .FCW_RST(FCW64[31:0])
  ) u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(),
    .fcw_o(cfg_fcw),
    .fcw_wr_o(),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status),
    .err_cnt_i(sts_err_cnt)
  );
  uart #(
    .CLK_HZ(CLK_HZ),
    .BAUD(BAUD),
    .FIFO_DEPTH(FIFO_DEPTH)
  ) u_core (
    .aclk,
    .aresetn,
    .s_axis_tdata,
    .s_axis_tvalid,
    .s_axis_tready,
    .s_axis_tlast,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .uart_txd_o,
    .uart_rxd_i,
    .cfg_ctrl,
    .cfg_fcw,
    .cfg_status,
    .cfg_status_wr,
    .sts_status,
    .sts_err_cnt
  );
endmodule
